import {initParticlesEngine} from "@tsparticles/react";
import {Particles} from "@tsparticles/react";
import { loadFull } from "@tsparticles/all";
import {loadSlim} from "@tsparticles/slim";
import { useCallback, useMemo } from "react";
import {useState, useEffect} from "react";

const ParticlesBg = (props)=>{
    const [init, setInit] = useState(false);
    useEffect(()=>{
        initParticlesEngine(async (engine)=>{
            await loadSlim(engine);
        }).then(()=>{
            setInit(true);
        });
    },[]);
    const particlesLoaded = (container) =>{
        console.log(container);
    };

    const options = useMemo(()=>({
        fullScreen: false,
        background:{
            color:{
                value: "transparent",
            },
        },
        fpsLimit: 120,
        interactivity:{
            events:{
                onClick:{
                    enable:true,
                    mode:"repulse",
                },
                onHover:{
                    enable:true,
                    mode:"grab",
                },
            },
            modes:{
                push:{
                    distance:200,
                    duration:15,
                },
                grab:{
                    distance:150,
                },
            },
        },
        particles:{
            color:{
                value:"#FFFFFF",
            },
            links:{
                color:"#FFFFFF",
                distance:150,
                enable:false,
                opacity:0.3,
                width:1,
            },
            move:{
                direction:"none",
                enable:true,
                outModes:{
                    default:"bounce",
                },
                random:true,
                speed:1,
                straight:false,
            },
            number:{
                density:{
                    enable:true,
                },
                value:150,
            },
            opacity:{
                value:1.0,
            },
            shape:{
                type:"circle",
            },
            size:{
                value:{min:1, max:5},
            },
        },
        detectRetina:true,
    }),
    [],
);
return <Particles id={props.id} init = {particlesLoaded} options = {options}/>;
};
export default ParticlesBg;