import React, {useState} from 'react';
import Certificate from './Certificate.jsx';
import ProLang from './ProLang.jsx';
import Skills from './Skills.jsx';
import book from '../images/book.png';
import degree from '../images/degrees.png';
import dev from '../images/dev.jpg';
import ParticlesBg from './ParticlesBg.js';

export default function Certifications(){
    const [setElement, setSelectedElem] = useState('');
    const handleClick= (element)=>{
        setSelectedElem(element);
    };
    const renderElem =()=>{
        switch(setElement){
            case 'lang':
                return <ProLang/>
            case 'cert':
                return <Certificate/>
            case 'skills':
                return <Skills/>
            default:
                return <ProLang/>
        }
    };

    return(
        <div className='cert-section'>
            <div className="p-container">
                <ParticlesBg/>
            </div>
            <h1>ACADEMIC    DEGREES AND CERTIFICATIONS</h1>
            <div className='cert-div'>
                <button onClick={()=> handleClick('lang')} className='home-btn-left'><img className='cert-menu-img' src={dev}/></button>
                <button onClick={()=> handleClick('cert')} className='home-btn-center'><img className='cert-menu-img' src={book}/></button>
                <button onClick={()=> handleClick('skills')} className='home-btn-right'><img className='cert-menu-img' src={degree}/></button>
            </div>
            {renderElem()}
        </div>
    );
}