
import {useState} from 'react';
import Home from './components/Home.jsx';
import AboutMe from './components/AboutMe.jsx';
import Certifications from './components/Certifications.jsx';
import cert from './images/cert.jpg';
import home from './images/home.jpg';
import about from './images/about.jpg';

function App() {
  const [selectedWin, setSelectedWin] = useState('home');
  const renderCase=()=>{
    switch(selectedWin){
      case 'home':
        return <Home/>;
      case 'about':
        return <AboutMe/>;
      case 'cert':
        return <Certifications/>
      default:
        return <Home/>;
    }
  };
  return (
    <div>
      <div className='menu-div'>
        <button onClick={()=>setSelectedWin('home')} className='menu-btn-left'><img src={home} className='menu-img' alt='home'/></button>
        <button onClick={()=>setSelectedWin('about')} className='menu-btn-center'><img src={about} className='menu-img' alt='home'/></button>
        <button onClick={()=>setSelectedWin('cert')} className='menu-btn-right'><img src={cert} className='menu-img' alt='home'/></button>
      </div>

      {renderCase()}
    </div>
  );
}

export default App;
