import lic from '../images/lic.png';
import master from '../images/master.png';
import titles from '../images/titles.jpg';
import React, {useState} from 'react';


export default function Skills(){
    const [setImg, setVisibleImg] = useState('tit-img');
    const showImg =()=>{
        setVisibleImg(setImg ==='tit-img' ? 'mas-img':'tit-img');
    }
    return(
        <div>
            <div className='deg-div'>
                <div className= 'deg-text'>
                    <h1>Here are my academic achievements</h1>
                    <p>I have a background in social sciences</p>
                    <h2>Master in Social and Communal Studies</h2>
                    <p>Centered in urban demographic policies and development</p>
                    <p>Focused on data analysis, demographic changes and policy efficiency</p>
                    <h2>Degree in Sociocultural Sciences</h2>
                    <p>Formation in social and cultural investigation and public policies</p>
                </div>
                <div className='deg-img-menu'>
                    <img src={lic} className='tit-img' style={{display: setImg === 'tit-img'? 'block':'none'}}/>
                    <img src={master} className='mas-img' style={{display: setImg === 'mas-img'? 'block':'none'}}/>
                </div>
            </div>
            <div className='div-btn-cont'>
                <button className='tit-btn' onClick = {showImg}><img src={titles} className = 'menu-img'/></button>
            </div>
        </div>
    );
}